package com.tal.pocketflow;
import android.app.*;import android.content.*;import android.widget.*;import android.os.Looper;import java.time.*;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class ReportPeriodTest {
 Context c;Store store;Store.Account bank;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.deleteDatabase("pocketflow.db");for(String p:new String[]{"prefs","security","google-drive","browser-sync"})c.getSharedPreferences(p,0).edit().clear().commit();store=new Store(c);bank=new Store.Account();bank.name="בנק";bank.type="bank";bank.start="2026-01-01";bank.closing=31;bank.charge=10;store.save(bank);}
 @After public void close(){store.close();}
 void configure(int day)throws Exception{JSONObject tools=Tools.read(c).put("periodStart",day);Tools.write(c,tools,false);}
 Store.Tx tx(String date,long amount,String kind,int status){Store.Tx t=new Store.Tx();t.date=date;t.amount=amount;t.originalAmount=amount;t.kind=kind;t.category="בית";t.account=bank.id;t.merchant="עסק";t.tag="נוגה";t.note="";t.count=1;t.status=status;store.save(t);return t;}
 @Test public void boundariesHaveNoGapsAcrossLeapMonthsAndYears(){for(int day=1;day<=31;day++){ReportPeriod p=new ReportPeriod(day);for(YearMonth m=YearMonth.of(2023,12);m.isBefore(YearMonth.of(2025,4));m=m.plusMonths(1)){assertEquals(p.start(m.plusMonths(1)),p.end(m).plusDays(1));assertEquals(m,p.label(p.start(m)));assertEquals(m,p.label(p.end(m)));assertEquals(m.minusMonths(1),p.label(p.start(m).minusDays(1)));}}ReportPeriod ten=new ReportPeriod(10);assertEquals(LocalDate.parse("2026-10-10"),ten.start(YearMonth.of(2026,10)));assertEquals(LocalDate.parse("2026-11-09"),ten.end(YearMonth.of(2026,10)));assertEquals(YearMonth.of(2026,10),ten.label(LocalDate.parse("2026-11-02")));}
 @Test public void overviewGraphsBudgetsAndSearchUseSameInclusiveWindow()throws Exception{configure(10);tx("2026-10-09",10000,"expense",1);Store.Tx original=tx("2026-10-10",20000,"expense",1);tx("2026-11-09",30000,"expense",0);tx("2026-11-10",40000,"expense",1);tx("2026-11-01",9000,"income",1);Store.Tx refund=new Store.Tx();refund.date="2026-11-02";refund.firstDue=refund.date;refund.refundOf=original.id;refund.amount=5000;refund.originalAmount=5000;refund.kind="refund";refund.category=original.category;refund.account=original.account;refund.merchant=original.merchant;refund.tag=original.tag;refund.note="";refund.count=1;refund.status=1;store.save(refund);YearMonth m=YearMonth.of(2026,10);assertEquals(45000,store.overview(m).total());assertEquals(45000,(long)store.overview(m).categories.get("בית"));assertEquals(45000,new Analytics(store,c).spend(m,""));assertEquals(15000,store.total(m,"expense"));assertEquals(9000,store.total(m,"income"));MovementFilter f=new MovementFilter();assertTrue(f.matches(original,m,store.reporting(),"",0,"",""));assertFalse(f.matches(store.transactions().get(0),m,store.reporting(),"",0,"",""));}
 @Test public void customDatesOverrideReportingWindow()throws Exception{configure(10);Store.Tx t=tx("2026-10-09",100,"expense",1);MovementFilter f=new MovementFilter();assertFalse(f.matches(t,YearMonth.of(2026,10),store.reporting(),"",0,"",""));f.from="2026-10-01";f.to="2026-10-31";assertTrue(f.matches(t,YearMonth.of(2026,10),store.reporting(),"",0,"",""));}
 @Test public void recurringDatesAreNotMovedAndNextCalendarMonthIsIncluded()throws Exception{Store.Rule r=new Store.Rule();r.name="מנוי";r.amount=10000;r.account=bank.id;r.category="בית";r.start="2026-10-01";r.end="";r.active=1;store.save(r);configure(10);YearMonth m=YearMonth.of(2026,10);store.ensureReportPeriod(m);List<Store.Tx> rows=store.month(m);assertEquals(1,rows.size());assertEquals("2026-11-01",rows.get(0).date);assertEquals(Arrays.asList(LocalDate.parse("2026-11-01")),store.reporting().ruleDates(r,m));assertEquals(10000,store.overview(m).recurring);assertEquals(10000,store.periodCharges(m).stream().mapToLong(x->x.amount).sum());assertEquals("2026-10-01",store.rules().get(0).start);}
 @Test public void paymentCalendarAndCreditFrameRemainExactlyTheSame()throws Exception{Store.Account a=new Store.Account();a.name="אשראי";a.type="fixed";a.start="2026-10-01";a.closing=9;a.charge=10;a.limit=5000000;a.opening=4364680;a.payment=500000;a.cycleConfigured=true;store.save(a);Store.Tx t=tx("2026-10-12",30000,"expense",1);t.account=a.id;store.save(t);String accounts=store.backup().getJSONArray("accounts").toString(),transactions=store.backup().getJSONArray("transactions").toString();long before=store.creditUsage(a,LocalDate.parse("2026-11-09")),after=store.creditUsage(a,LocalDate.parse("2026-11-10"));String charge=chargeSignature(store.charges(YearMonth.of(2026,11)));configure(10);assertEquals(accounts,store.backup().getJSONArray("accounts").toString());assertEquals(transactions,store.backup().getJSONArray("transactions").toString());assertEquals(before,store.creditUsage(a,LocalDate.parse("2026-11-09")));assertEquals(after,store.creditUsage(a,LocalDate.parse("2026-11-10")));assertEquals(charge,chargeSignature(store.charges(YearMonth.of(2026,11))));assertTrue(store.periodCharges(YearMonth.of(2026,10)).stream().noneMatch(x->x.date.equals(LocalDate.parse("2026-11-10"))));assertTrue(store.periodCharges(YearMonth.of(2026,11)).stream().anyMatch(x->x.date.equals(LocalDate.parse("2026-11-10"))));}
 String chargeSignature(List<Store.Charge> charges){StringBuilder b=new StringBuilder();for(Store.Charge q:charges)b.append(q.date).append(':').append(q.amount).append(':').append(q.account).append(';');return b.toString();}
 @Test public void partialComparisonAndCumulativeUseElapsedDaysAcrossMonthBoundary()throws Exception{configure(10);tx("2026-09-10",10000,"expense",1);tx("2026-09-13",90000,"expense",1);tx("2026-10-10",15000,"expense",1);tx("2026-10-13",50000,"expense",1);Analytics a=new Analytics(store,c);YearMonth selected=YearMonth.of(2026,10);LocalDate today=LocalDate.parse("2026-10-12");assertTrue(a.insights(selected,today).stream().anyMatch(i->i.title.contains("50%")));Store.SeriesData series=store.cumulative(selected,today);assertEquals(3,series.labels.size());assertArrayEquals(new long[]{15000,15000,15000},series.series.get("החודש הנבחר"));assertArrayEquals(new long[]{10000,10000,10000},series.series.get("החודש הקודם"));assertEquals(LocalDate.parse("2026-09-12"),store.reporting().comparisonEnd(selected,today));assertEquals(0,store.cumulative(selected.plusMonths(1),today).labels.size());}
 @Test public void settingsBackupAndUndoPreserveReportingDayAndRejectInvalidBackup()throws Exception{JSONObject before=store.backup();store.edit("תקופה",()->Tools.write(c,new JSONObject().put("periodStart",10),false));assertEquals(10,store.reporting().day);store.undo();assertEquals(1,store.reporting().day);configure(31);JSONObject saved=store.backup();store.restore(before);assertEquals(1,store.reporting().day);store.restore(saved);assertEquals(31,store.reporting().day);saved.getJSONObject("settings").getJSONObject("tools").put("periodStart",32);try{store.restore(saved);fail();}catch(IllegalArgumentException expected){}assertEquals(31,store.reporting().day);}
 @Test public void budgetAlertsChooseCurrentReportingPeriodBeforeTenth()throws Exception{configure(10);tx("2026-10-20",8500,"expense",1);Tools.write(c,Tools.read(c).put("budgets",new JSONObject().put("",10000)),false);assertTrue(new Analytics(store,c).alerts(LocalDate.parse("2026-11-02")).stream().anyMatch(x->x.contains("85%")));assertTrue(new Analytics(store,c).alerts(LocalDate.parse("2026-11-10")).isEmpty());}
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) @Config(qualifiers="he-rIL-w411dp-h891dp-xxhdpi") public void uiSettingChangesOverviewExportAndSurvivesRecreation()throws Exception{configure(1);tx("2026-10-20",1200,"expense",1);tx("2026-11-02",3400,"expense",1);try(ActivityController<MainActivity> ctl=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=ctl.get();StoreTest.navigate(a,5);a.getWindow().getDecorView().findViewWithTag("report-period-setting").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();((EditText)d.getWindow().getDecorView().findViewWithTag("report-period-day")).setText("10");d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertFalse(ShadowToast.getTextOfLatestToast(),d.isShowing());assertEquals(10,store.reporting().day);StoreTest.navigate(a,0);java.lang.reflect.Field field=MainActivity.class.getDeclaredField("month");field.setAccessible(true);field.set(a,YearMonth.of(2026,10));java.lang.reflect.Method redraw=MainActivity.class.getDeclaredMethod("render");redraw.setAccessible(true);redraw.invoke(a);assertTrue(((TextView)a.getWindow().getDecorView().findViewWithTag("home-total")).getText().toString().contains("46.00"));java.lang.reflect.Method range=MainActivity.class.getDeclaredMethod("periodRange",YearMonth.class);range.setAccessible(true);assertEquals("10/10/2026 – 09/11/2026",range.invoke(a,YearMonth.of(2026,10)));Upgrade012Test renderer=new Upgrade012Test();renderer.snapshot(a.getWindow().getDecorView(),"reporting-10-home");ctl.recreate();a=ctl.get();assertEquals(YearMonth.of(2026,10),field.get(a));java.lang.reflect.Method csv=MainActivity.class.getDeclaredMethod("exportCsv");csv.setAccessible(true);csv.invoke(a);java.lang.reflect.Field exported=MainActivity.class.getDeclaredField("pendingExport");exported.setAccessible(true);String data=(String)exported.get(a);assertTrue(data.contains("2026-10-20"));assertTrue(data.contains("2026-11-02"));}}
}
